INSERT INTO Questoes (Enunciado, Opcao_a, Opcao_b, Opcao_c, Opcao_d, Opcao_e, Resposta_correta) VALUES
('O que era exatamente o Therac-5 e qual era a sua finalidade primária na medicina?', 'Um sistema de diagnóstico por imagem para detecção de tumores.', 'Um acelerador linear de elétrons utilizado em radioterapia para destruição de tecidos cancerígenos.', 'Um equipamento de ressonância magnética de alta precisão.', 'Um tomógrafo computadorizado com emissão de pósitrons (PET-Scan).', 'Um robô cirúrgico para procedimentos minimamente invasivos.','B'),
('Qual foi a empresa canadense responsável pelo projeto e fabricação do Therac-5?', 'General Electric Medical Systems Canada.', 'Siemens Healthineers Canada.', 'Bombardier Medical Robotics.', 'Atomic Energy of Canada Limited (AECL).', 'Philips Medical Systems Canada.', 'D'),
('Entre quais anos ocorreram os acidentes graves de sobredosagem de radiação documentados?', '985 e 98.', '95 e 98.', '99 e 99.', '998 e 00.', '980 e 98.', 'A'),
('Quantos acidentes de sobredosagem massiva de radiação foram oficialmente confirmados pelo estudo de Leveson?', ' acidentes.', ' acidentes.', ' acidentes.', '5 acidentes.', ' acidente acumululado.', 'C'),
('Quais são os dois modos de tratamento terapêutico que a máquina Therac-5 oferecia?', 'Modo Ultrassom e Modo Laser de Alta Intensidade.', 'Modo Radiação Gama e Modo Próton-terapia.', 'Modo Termoterapia e Modo Crioterapia.', 'Modo Tomografia e Modo Ressonância.', 'Modo Eletrons (direto) e Modo Photons (Raio-X de alta energia).', 'E'),
('O que era o Therac-5: um equipamento totalmente novo ou a evolução de modelos anteriores?', 'Projeto criado do zero, sem reaproveitamento de conceitos.', 'Evolução dos modelos Therac- e Therac-0.', 'Versão modificada de um acelerador industrial europeu.', 'Protótipo acadêmico nunca comercializado antes.', 'Cópia direta de um acelerador americano concorrente.', 'B'),
('Qual era a principal inovação técnica do Therac-5 em relação aos seus antecessores Therac- e Therac-0?', 'O uso de inteligência artificial para calcular a dose.', 'A inclusão de um braço robótico articulado de  eixos.', 'A substituição do terminal por tela touchscreen.', 'A eliminação das intertravas mecânicas de hardware, confiando a segurança totalmente ao software.', 'A utilização de supercondutores criogênicos.', 'D'),
('Que sintoma imediato e incomum os pacientes relatavam sentir durante os disparos acidentais?', 'Sensação de choque elétrico, dor aguda e sensação de queimadura/calor intenso.', 'Tontura instantânea e perda temporária da visão.', 'Parestesia súbita nos membros inferiores.', 'Náuseas violentas e perda auditiva imediata.', 'Paralisia temporária dos membros superiores.', 'A'),
('Qual era o erro exibido na tela do operador quando o sistema aplicava uma overdose sem aviso prévio?', 'CRITICAL HARDWARE FAILURE.', 'RADIATION OVERFLOW DETECTED.', 'MALFUNCTION 5 (ou outro número genérico de Malfunction).', 'SYSTEM SHUTDOWN EMERGENCY.', 'FATAL MEMORY OVERFLOW.', 'C'),
('O que significavam os códigos de erro genéricos ("MALFUNCTION") exibidos no terminal de controle?', 'O número indicava exatamente qual peça estava quebrada.', 'Aviso de que o paciente se movimentou durante o disparo.', 'Confirmação de que o tratamento fora concluído.', 'Falha crítica no disco rígido do computador principal.', 'Mensagens genéricas indicando que o feixe parou por inconsistência, sem especificar a gravidade.', 'E'),
('Qual foi a principal consequência para a saúde das vítimas expostas às sobredosagens do Therac-5?', 'Desenvolvimento de catarata precoce sem lesões cutâneas.', 'Apenas eritemas leves que desapareciam em  horas.', 'Queimaduras radiológicas severas, necrose tecidual e morte de vários pacientes.', 'Alterações assintomáticas detectadas apenas em exames de sangue.', 'Perda total dos movimentos musculares sem lesões na pele.', 'C'),
('O software do Therac-5 foi escrito em qual linguagem de programação?', 'Assembly (PDP-).', 'C++', 'FORTRAN .', 'Pascal.', 'Cobol.', 'A'),
('Em qual processador o sistema de controle do Therac-5 era executado?', 'Intel 808.', 'Motorola 8000.', 'Zilog Z80.', 'PowerPC G.', 'PDP- (DEC).', 'E'),
('Quantas vezes acima da dose prescrita a máquina aplicava quando ocorria a falha de feixe direto?', 'Cerca de ,5 a  vezes a dose.', 'Cerca de 00 a 5 vezes a dose normal.', 'Exatamente 0 vezes a dose.', 'Aproximadamente 500 vezes a dose.', '000 vezes a dose prescrita.', 'B'),
('Quem foi a pesquisadora de segurança de software responsável pelo relatório clássico que analisou o caso?', 'Grace Hopper.', 'Margaret Hamilton.', 'Barbara Liskov.', 'Nancy Leveson.', 'Ada Lovelace.', 'D'),
('Que componente físico crucial de segurança (intertrava mecânica) foi removido no Therac-5?', 'Os fusíveis elétricos da tomada de parede.', 'O botão de desligamento de emergência da sala.', 'O circuito independente de intertrava de hardware do carrossel/placa de alvo.', 'A blindagem de chumbo das paredes do bunker.', 'O disjuntor geral do gerador de alta voltagem.', 'C'),
('A interface do operador utilizava que tipo de terminal para entrada de dados e comandos?', 'Terminal de vídeo DEC VT00 com teclado.', 'Leitor de cartões perfurados IBM.', 'Painel analógico com chaves comutadoras.', 'Teclado numérico com display de  segmentos.', 'Monitor LCD touchscreen resistivo.', 'A'),
('O que acontecia quando o operador pressionava a tecla \''P\'' (Proceed) após o erro "Malfunction 5"?', 'O sistema abortava o tratamento e reiniciava.', 'A máquina abria o manual de instruções na tela.', 'O feixe era reduzido automaticamente para %.', 'O computador entrava em modo de segurança.', 'O erro era ignorado e a máquina aplicava mais uma dose massiva de radiação.', 'E'),
('Qual era a reação inicial dos técnicos do fabricante quando os hospitais notificavam suspeitas de overdose?', 'Interrompiam as vendas imediatamente.', 'Afirmavam que era impossível haver overdose por software e atribuíam ao erro do operador.', 'Contratavam auditorias externas no mesmo dia.', 'Substituíam todos os computadores das clínicas.', 'Realizavam recall voluntário em 8 horas.', 'B'),
('Qual órgão regulador governamental dos EUA interveio no caso exigindo planos de ação corretiva?', 'NASA.', 'FCC.', 'OSHA.', 'FDA (Food and Drug Administration).', 'EPA.', 'D'),
('O código de software do Therac-5 foi testado de forma independente antes de ser colocado no mercado comercial?', 'Sim, por três órgãos de certificação internacionais.', 'Sim, por uma equipe de hackers especializados.', 'Sim, através de simulação formal em supercomputadores.', 'Não, os testes de software foram mínimos e não houve validação independente.', 'Sim, por auditores do governo canadense.', 'D'),
('Quantas pessoas morreram diretamente em decorrência dos acidentes de radiação do Therac-5?', 'Nenhuma (houve apenas ferimentos leves).', 'Pelo menos  a 5 fatalidades diretamente comprovadas.', 'Mais de 00 pessoas.', 'Exatamente 8 pessoas.', 'Apenas uma pessoa idosa.', 'B'),
('O que é uma "condição de corrida" (race condition) no contexto de software?', 'Um bug que faz o processador rodar com overclock.', 'Um vírus que acelera o consumo de memória RAM.', 'Uma falha onde o resultado depende da ordem ou do tempo relativo de execução de tarefas concorrentes.', 'Um erro de digitação cometido ao escrever laços de repetição.', 'Um conflito de endereçamento IP na rede local.', 'C'),
('Qual era a função do "alvo de tungstênio/ouro" (target) no modo de Raio-X de alta energia?', 'Absorver os elétrons para convertê-los em um feixe de fótons (Raio-X).', 'Servir de espelho para alinhar o laser visível.', 'Resfriar os magnéticos de curvamento.', 'Medir a temperatura ambiente do bunker.', 'Filtrar os raios gama indesejados.', 'A'),
('O Therac-5 continuou sendo vendido normalmente após os relatórios de acidentes fatais em 98?', 'Sim, continuou no mercado por mais 0 anos.', 'Sim, mas apenas para clínicas veterinárias.', 'Sim, com desconto de 50% em peças.', 'Sim, sob nova marca comercial.', 'Não, sofreu suspensão e recall até que modificações fossem implementadas.', 'E'),
('Como os operadores podiam pausar e retomar um tratamento no console da máquina?', 'Cortando a energia elétrica da parede.', 'Girando uma chave física no pedal.', 'Digitando a senha de administrador.', 'Pressionando a tecla \''P\'' ou barra de espaço para pausar/prosseguir no terminal.', 'Desconectando o cabo serial do teclado.', 'D'),
('O que acontecia se o operador tentasse alterar um valor digitado incorretamente no terminal?', 'O sistema emitia bipe e bloqueava o teclado por 0 minutos.', 'O cursor subia para corrigir o campo, abrindo a janela de tempo que acionava a condição de corrida.', 'A tela apagava e apagava a ficha do paciente.', 'A máquina executava calibração automática.', 'O computador reiniciava em modo de diagnóstico.', 'B'),
('Qual era a promessa comercial da AECL em relação à automação no Therac-5?', 'Eliminar a necessidade de físicos hospitalares.', 'Curar o câncer em metade das sessões.', 'Reduzir o tempo de preparação do tratamento e aumentar a eficiência operacional das clínicas.', 'Permitir controle remoto via linha telefônica.', 'Reduzir o custo operacional em 90%.', 'C'),
('Em que país ficava a sede da AECL (Atomic Energy of Canada Limited)?', 'Canadá.', 'Estados Unidos.', 'Reino Unido.', 'Alemanha.', 'França.', 'A'),
('Qual era o objetivo da radiação aplicada pelo Therac-5 em pacientes com câncer?', 'Queimar verrugas superficiais na pele.', 'Aquecer os tecidos para melhorar a circulação.', 'Esterilizar instrumentos cirúrgicos.', 'Reduzir a dor crônica nas articulações.', 'Destruir células tumorais e retardar ou impedir o crescimento de neoplasias.', 'E'),
('Quais eram as unidades de medida utilizadas para definir a dose de radiação administrada?', 'Rads (ou Grays).', 'Volts e Amperes.', 'Joules por segundo.', 'Candelas e Lumens.', 'Hertz e Decibéis.', 'A'),
('Como a máquina sinalizava visualmente que o feixe de radiação estava ativo?', 'Apagando todas as luzes da sala.', 'Ativando um giroscópio luminoso no teto.', 'Por meio de um indicador/luz de "BEAM ON" na tela e no painel do console.', 'Mudando a cor do monitor para vermelho brilhante.', 'Emitindo raios laser coloridos no ambiente.', 'C'),
('Os operadores do Therac-5 ficavam na mesma sala que o paciente durante o disparo do feixe?', 'Sim, ao lado da maca segurando a mão do paciente.', 'Não, ficavam em uma sala de controle externa blindada com intercomunicador e monitor de TV.', 'Dependia do tipo de tumor a ser tratado.', 'Ficavam atrás de uma cortina plástica dentro da sala.', 'Ficavam no andar superior do hospital.', 'B'),
('Qual foi o destino final das máquinas Therac-5 instaladas nos hospitais após as investigações?', 'Foram todas destruídas e derretidas no mesmo ano.', 'Doadas sem alterações para países emergentes.', 'Convertidas em aparelhos de raio-X odontológicos.', 'Desmontadas e transformadas em servidores de rede.', 'Sofreram modificações obrigatórias de software e instalação de intertravas mecânicas de hardware.', 'E'),
('Como a velocidade de digitação de operadores experientes contribuiu diretamente para o disparo do bug no Therac-5?', 'Os operadores digitavam tão rápido que travavam o teclado fisicamente, gerando um curto-circuito.', 'A velocidade excessiva enviava comandos em código ASCII corrompido para o processador.', 'O sistema interpretava a digitação rápida como um ataque de negação de serviço e reiniciava em modo de emergência.', 'A digitação rápida das correções (em menos de 8 segundos) permitia alterar o modo do feixe enquanto a rotina de configuração do feixe ainda estava em execução em segundo plano sem a trava adequada.', 'Acelerava o relógio interno do computador corrompendo a contagem dos minutos.', 'D'),
('Qual é a diferença física e operacional fundamental entre o modo "Eletrons" e o modo "Photons" (Raio-X)?', 'O modo Eletrons utiliza corrente baixa e feixe direto; o modo Photons utiliza corrente até 00 vezes maior contra um alvo metálico conversor.', 'O modo Eletrons necessita do alvo de tungstênio, enquanto o modo Photons necessita do espalhador de alumínio.', 'O modo Photons opera com voltagem nula, enquanto o modo Eletrons opera com voltagem máxima.', 'O modo Eletrons é destinado apenas a tumores profundos e o Photons a tumores de pele.', 'Não há diferença física, apenas alteração na cor da interface visual.', 'A'),
('Descreva a falha do estouro de variável (overflow) no código de verificação do posicionamento do braço giratório.', 'Uma variável de  bits estourava após .000 horas continuas de uso da máquina.', 'O estouro de memória RAM fazia o sistema operacional sobrescrever os dados cadastrais do paciente.', 'Um contador de  byte (0 a 55) incrementava a cada iteração de teste e, ao atingir 5voltava a zero (Class = 0), fazendo o software interpretar erroneamente que o posicionamento estava correto e verificado.', 'O estouro da variável de dosimetria fazia a máquina desligar os motores antes de posicionar a mesa.', 'A variável de controle do relógio estourava a cada  horas de operação contínua.', 'C'),
('Por que o reuso de código do Therac- e Therac-0 para o Therac-5 criou uma falsa sensação de segurança?', 'Porque o código original havia sido escrito em uma linguagem de programação moderna e sem erros.', 'Porque nos modelos antigos as intertravas mecânicas de hardware mascaravam e preveniam as falhas de software que já existiam no código reusado.', 'Porque o software antigo havia sido certificado pela NASA para missões espaciais.', 'Porque os modelos antigos utilizavam inteligência artificial para autofixação de bugs.', 'Porque o código reusado era totalmente imune a condições de corrida.', 'B'),
('Qual era a sequência de ações no terminal VT00 que ativava o bug de edição rápida de parâmetros?', 'Pressionar a tecla \''Ctrl+Alt+Del\'' repetidamente durante o disparo do feixe.', 'Digitar \''P\'' (Proceed) antes de selecionar o nome do paciente no banco de dados.', 'Segurar a barra de espaço por mais de 0 segundos na tela principal de logon.', 'Executar o comando de formatação do disco rígido pelo terminal.', 'Digitar o modo de Raio-X (\''X\''), perceber o erro, usar a tecla de subir cursor para alterar para Elétrons (\''E\'') e pressionar \''Enter\'' em menos de 8 segundos.', 'E'),
('O que acontecia fisicamente com o feixe de elétrons quando a máquina disparava no modo Raio-X sem o alvo metálico posicionado?', 'O feixe era bloqueado por uma parede de chumbo móvel sem atingir a sala.', 'O tubo de vácuo do acelerador explodia devido à alta pressão de ar.', 'A máquina emitia apenas uma luz visível azul sem radiação ionizante.', 'Um feixe de elétrons de alta corrente e estreito (pencil beam) atingia diretamente o corpo do paciente sem atenuação ou espalhamento.', 'O feixe desviava automaticamente para o teto da sala de tratamento.', 'D'),
('Como a ausência de feedback claro de erro levou os operadores a repetirem a aplicação de dose no mesmo paciente?', 'O monitor desligava completamente, forçando o operador a adivinhar o status.', 'O sistema informava na tela que a sessão havia sido cancelada com sucesso antes da emissão.', 'A impressora gerava um comprovante afirmando que o feixe falhara em ligar.', 'O sistema exibia uma tela azul de erro fatal que pedia para reiniciar a máquina.', 'A tela exibia apenas "MALFUNCTION 5" e indicava subdose/não entrega, induzindo o operador a pressionar \''P\'' (Proceed) para tentar reaplicar a dose prescrita.', 'E'),
('O que caracterizava a rotina do sistema operacional de tempo real (RTOS) do Therac-5?', 'Um sistema operacional comercial Linux com gerenciamento rigoroso de memória virtual.', 'O uso do Windows NT Workstation em arquitetura de  bits.', 'A ausência de qualquer suporte a concorrência ou interrupções de hardware.', 'Um RTOS artesanal e pré-emptivo sem mecanismos adequados de sincronização e proteção de memória compartilhada.', 'Um sistema operacional em tempo real desenvolvido em linguagem C pela Microsoft.', 'D'),
('De que maneira a AECL testou a confiabilidade do software antes de declarar que o sistema era seguro?', 'Realizou testes básicos integrados ao hardware, assumindo que o software era perfeito por não ter partes móveis sujeitas a desgaste.', 'Submeteu o código a simulações de verificação formal por Redes de Petri por  anos.', 'Contratou uma empresa independente de auditoria em engenharia de software na Europa.', 'Deixou o código em teste aberto na comunidade acadêmica por 8 meses.', 'Executou testes de estresse com 0.000 horas de simulação virtual.', 'A'),
('Por que as intertravas físicas de hardware presentes no Therac-0 mascaravam os bugs de software que já existiam?', 'O hardware reescrevia o código do software automaticamente no disco rígido.', 'Quando o software enviava um comando inválido ou perigoso, o circuito mecânico cortava a energia do feixe antes do disparo, impedindo o acidente.', 'As intertravas desligavam a tela do operador para esconder os relatórios de erro.', 'O hardware gerava relatórios semanais de bugs para os engenheiros da AECL.', 'As peças mecânicas bloqueavam o teclado do terminal durante falhas lógicas.', 'B'),
('Qual foi o papel do físico hospitalar Fritz Hager no Northfield Cancer Center (Tyler, Texas)?', 'Ele projetou a primeira versão do software do Therac-5.', 'Ele foi o responsável por defender a AECL nos tribunais internacionais.', 'Ele trabalhou rigorosamente com a operadora do hospital para reproduzir a sequência exata de comandos que acionava a falha do software de forma consistente.', 'Ele desenvolveu a vacina contra os efeitos da sobredosagem por radiação.', 'Ele coordenou o recall mundial das máquinas.', 'C'),
('Explique como a variável `Class` incrementava e por que o valor zero liberava o feixe inapropriadamente.', 'A variável `Class` registrava a temperatura do bunker e desativava a segurança ao congelar em zero.', 'O valor zero forçava o processador a entrar em loop infinito de reinicialização.', '`Class` era o identificador do paciente e, se fosse zero, o tratamento era aplicado no modo de teste.', 'A variável contava os ciclos de clock da CPU e liberava o feixe ao esgotar a memória.', 'A variável `Class` acumulava erros de hardware; o valor zero indicava ausência de erros, fazendo o sistema liberar o feixe mesmo com os componentes desalinharados.', 'E'),
('Quantas rads (unidade de radiação) eram entregues em um disparo acidental versus a dose terapêutica normal?', 'Exatamente 50 rads no disparo acidental contra 500 rads na dose normal.', 'Cerca de .000.000 rads no disparo acidental contra 0.000 rads na dose normal.', 'A overdose entregava apenas 5 rads a mais do que a dose prescrita.', 'Cerca de 0.000 a 5.000 rads no disparo acidental, contra uma dose normal de 00 a 00 rads.', '500 rads no disparo acidental contra 50 rads na dose normal.', 'D'),
('Quais foram alguns dos locais onde ocorreram acidentes documentados do Therac-5?', 'Kennestone (Georgia), Hamilton (Ontário), Tyler (Texas) e Yakima (Washington).', 'Nova York (EUA), Londres (Reino Unido), Paris (França) e Tóquio (Japão).', 'São Paulo (Brasil), Buenos Aires (Argentina) e Santiago (Chile).', 'Toronto (Canadá), Ottawa (Canadá) e Quebec (Canadá) exclusivamente.', 'Berlim (Alemanha), Roma (Itália) e Madri (Espanha).', 'A'),
('Como a arquitetura multithreading sem mecanismos adequados de sincronização (mutexes) afetou o sistema?', 'Impediu o computador de ligar quando conectado à rede elétrica.', 'Permitiu que a tarefa de interface do usuário alterasse variáveis de configuração críticas enquanto a tarefa de controle do feixe já as lia/processava.', 'Fez a memória RAM apagar todas as variáveis a cada 5 minutos.', 'Duplicou o tamanho do arquivo executável do software.', 'Causou o travamento total da CPU ao tentar ler arquivos em disquete.', 'B'),
('Qual foi a resposta e exigência oficial da FDA americana após a notificação dos acidentes?', 'Determinou o banimento eterno de qualquer computador em equipamentos médicos.', 'Multou apenas os operadores do hospital sem responsabilizar a fábrica.', 'Exigiu a elaboração e execução de Planos de Ação Corretiva (CAP), incluindo mudanças estruturais de software e instalação de intertravas mecânicas.', 'Aprovou a máquina para venda livre em farmácias e postos de saúde.', 'Encerrou as atividades do órgão regulador por conflito de interesses.', 'C'),
('Por que a rotina `Datain` permitia que o operador modificasse a configuração enquanto o curvamento do feixe se ajustava?', 'Porque foi desenhada intencionalmente para permitir o ajuste fino durante o tratamento.', 'Porque não havia checagem de concorrência que impedisse o operador de editar a tela durante o ciclo de posicionamento dos magnéticos (que levava cerca de 8 segundos).', 'Para economizar energia elétrica do circuito de refrigeração.', 'Porque a rotina operava em um computador separado instalado na recepção do hospital.', 'Para permitir o cancelamento imediato de comandos digitados por engano.', 'B'),
('O que significava o termo "segurança por design" (safety-by-design) e como ele foi violado no Therac-5?', 'Significa colocar etiquetas coloridas de aviso no gabinete da máquina; foi violado ao usar a cor azul no lugar da amarela.', 'Significa contratar guardas de segurança para vigiar a sala; foi violado ao deixar a porta destrancada.', 'Significa criar senhas de acesso fortes para o console; foi violado ao usar "".', 'Significa atualizar o antivírus diariamente; foi violado ao usar disquetes infectados.', 'Significa construir o sistema com barreiras de proteção físicas/arquiteturais inerentes; foi violado ao confiar a segurança crítica unicamente ao software sem redundância de hardware.', 'E'),
('Como a documentação técnica deficiente do software dificultou as investigações internas da própria AECL?', 'A documentação estava escrita em um idioma fictício criado pelo programador.', 'Os manuais foram queimados em um incêndio culposo na fábrica da AECL.', 'O código fonte estava protegido por uma chave de criptografia militar indecodificável.', 'Não havia comentários no código nem especificações formais de requisitos, tornando quase impossível rastrear a lógica e reproduzir as falhas.', 'Os registros de engenharia foram totalmente digitalizados em formatos proprietários perdidos.', 'D'),
('Qual era a proporção da taxa de corrente do feixe de elétrons no modo Raio-X comparada com o modo Elétrons direto?', 'A corrente no modo Raio-X era idêntica à do modo Eletrons.', 'A corrente no modo Raio-X era 0 vezes menor para proteger o paciente.', 'A corrente no modo Raio-X era cerca de 00 vezes maior para compensar a perda na conversão no alvo metálico.', 'A corrente no modo Eletrons era 50 vezes maior do que no modo Raio-X.', 'A corrente no modo Raio-X era nula devido à ausência do alvo.', 'C'),
('Como os engenheiros da AECL tentaram reproduzir o erro inicialmente e por que falharam em seus primeiros testes?', 'Testaram pressionando teclas aleatoriamente e em velocidade normal/lenta, sem conseguir replicar o timing exato da digitação rápida do operador experiente.', 'Utilizaram computadores de marcas diferentes dos instalados nos hospitais.', 'Realizaram os testes com a máquina totalmente desligada da tomada.', 'Testaram apenas o modo de calibração por ultrassom.', 'Conectaram o sistema à internet pública gerando instabilidade de rede.', 'A'),
('O que era o "Pencil Beam" e por que sua aplicação direta e sem espalhamento foi devastadora?', 'Um feixe de luz laser de baixa intensidade usado para desenhar marcas na pele do paciente.', 'Um feixe de elétrons altamente concentrado e não atenuado que depositou uma densidade de energia extrema em uma área minúscula de tecido biológico.', 'Uma agulha cirúrgica acoplada ao braço robótico para biópsias.', 'Um instrumento de calibração óptica utilizado antes do atendimento.', 'Um feixe de radiação gama de baixa intensidade para exames gerais.', 'B'),
('Qual foi o impacto de responsabilizar inicialmente o operador por "erro humano" na gestão da tragédia?', 'Resolveu o problema rapidamente e evitou novos acidentes nos outros hospitais.', 'Reduziu o custo das apólices de seguro médico da instituição.', 'Forçou os operadores a fazerem cursos superiores de datilografia antes de operar a máquina.', 'Melhorou a precisão dos registros clínicos nos prontuários eletrônicos.', 'Atrasou a identificação da causa raiz no software, permitindo que o mesmo bug ocorresse novamente e vitimasse outros pacientes.', 'E'),
('De que modo as modificações temporárias de hardware aplicadas pela AECL falharam em resolver a causa raiz?', 'As modificações queimavam a placa-mãe do PDP- assim que a máquina era ligada.', 'As peças de substituição eram importadas e demoravam 5 anos para chegar.', 'A alteração desativou o monitor de vídeo da sala de controle.', 'A AECL adicionou apenas capacitores na fiação externa sem corrigir as condições de corrida e estouros de variável existentes no software.', 'Os componentes de hardware instalados eram incompatíveis com a tensão elétrica dos EUA.', 'D'),
('Que importante norma/princípio de engenharia médica emergiu diretamente das lições do Therac-5?', 'A proibição total do uso de software em ambientes de terapia médica.', 'A exigência de que todos os programadores médicos tenham diploma em Medicina.', 'A obrigatoriedade do desenvolvimento rigoroso de software crítico com análise de riscos, verificação independente e intertravas de hardware redundantes (ex: IEC 0 / ISO 9).', 'A padronização dos teclados de controle no formato azerty.', 'A exclusão de testes de integração em dispositivos de classe III.', 'C'),
('Como era realizada a calibração dos sensores de radiação e por que ela não preveniu os disparos incorretos?', 'A calibração media a resposta dos sensores a baixas dosagens, mas as câmaras de ionização saturavam diante do disparo massivo de corrente do feixe direto, falhando em ler a overdose a tempo de interrompê-la.', 'A calibração era feita utilizando um termômetro culinário comum.', 'Os sensores eram desativados durante a calibração para evitar desgaste.', 'O procedimento de calibração era realizado apenas uma vez a cada dez anos pelo fabricante.', 'Os sensores mediam apenas a temperatura ambiente da sala e não a radiação.', 'A'),
('Qual era o papel do carrossel (turntable) no funcionamento físico do Therac-5?', 'Girar a maca do paciente em 0 graus para exames de imagem.', 'Misturar os reagentes químicos usados no contraste do paciente.', 'Posicionar os componentes adequados no caminho do feixe (alvo metálico para Raio-X, folha espalhadora para Elétrons ou espelho para alinhamento óptico).', 'Resfriar o gerador de alta voltagem do acelerador linear.', 'Armazenar os acessórios cirúrgicos esterilizados.', 'C'),
('De que forma a interface de usuário do Therac-5 omitia informações sobre o estado real do feixe?', 'A interface omitia o nome e a idade do paciente em tratamento.', 'O monitor ficava completamente em branco durante o disparo de radiação.', 'O sistema exibia dados de outro paciente que estava em tratamento na sala ao lado.', 'Não exibia a corrente real do feixe nem o estado dos componentes de hardware em tempo real, mostrando apenas parâmetros teóricos prescritos.', 'Exibia códigos de erro em formato binário ilegível para os técnicos.', 'D'),
('Por que o teste de software em isolamento não conseguiu identificar a condição de corrida em ambiente multitarefa?', 'Porque os testes duravam apenas  segundos.', 'Porque os testes de caixa-preta avaliavam apenas pares de entrada/saída esperados sob condições normais, sem analisar temporizações assíncronas do teclado real.', 'Porque o código testado era escrito em uma linguagem diferente da versão de produção.', 'Porque os engenheiros usaram computadores analógicos para simular o código digital.', 'Porque os arquivos de teste foram apagados acidentalmente antes da compilação.', 'B'),
('Como as alterações na tela podiam ser gravadas sem validação no Therac-5?', 'Qualquer pessoa na internet podia alterar o arquivo via rede externa.', 'As alterações eram salvas automaticamente em disquetes sem proteção contra gravação.', 'O sistema lia comandos enviados por ondas de rádio comerciais sem autenticação.', 'O operador podia editar o código-fonte executável diretamente no console de comandos.', 'O sistema salvava as alterações temporárias no buffer de dados antes de concluir a validação completa de segurança dos parâmetros modificados.', 'E'),
('Qual foi a diferença na atitude investigativa da clínica de Tyler (Texas) em relação às outras instituições afetadas?', 'A equipe médica e o físico de Tyler recusaram-se a aceitar a explicação de "erro humano", investigando ativamente até conseguir reproduzir o bug do software.', 'A clínica simplesmente aposentou a máquina e comprou um modelo concorrente no dia seguinte.', 'A clínica de Tyler processou o paciente por danos morais à imagem do hospital.', 'A clínica escondeu os fatos do público e da FDA por mais de cinco anos.', 'Tyler contratou os engenheiros da AECL para gerenciar a radioterapia local.', 'A'),
('Por que a AECL continuou afirmando que era "impossível" haver overdose por software mesmo após múltiplos casos?', 'Porque os engenheiros haviam recebido um prêmio internacional de software livre de erros.', 'Para inflar o preço das ações da empresa na bolsa de valores durante a fusão.', 'Devido ao excesso de confiança no código reusado do Therac-0 e à falta de compreensão da diferença que a remoção do hardware de segurança causava.', 'Porque o sistema operacional possuía uma garantia por escrito emitida pela DEC.', 'Porque os relatórios médicos eram falsificados pelas próprias clínicas.', 'C'),
('Qual era a função da folha espalhadora (foil) no modo de elétrons e como sua ausência alterava a dosimetria?', 'Servia para concentrar o feixe em um ponto microscópico; sem ela, o feixe se espalhava e perdia a eficácia.', 'Resfriar o tubo de aceleração de partículas; sem ela, a máquina derretia em 5 segundos.', 'Filtrar os fótons de luz visível para evitar o aquecimento da pele.', 'Servia para espalhar o feixe estreito de elétrons de forma homogênea sobre a área do tumor; sem ela, o feixe concentrado aplicava uma dose letal localizada.', 'Servia para medir a umidade relativa do ar dentro do cabeçote.', 'D'),
('Interface no Therac-5.', 'As duas tarefas rodavam em processadores fisicamente separados e se comunicavam via cabo de rede sem perdas.', 'A tarefa de interface alterava a flag de edição (`shared memory`) sem usar exclusão mútua, enquanto a tarefa de controle consumia o estado inconsistente durante a movimentação dos magnéticos.', 'A tarefa de controle travava o sistema operacional sempre que a tecla \''X\'' era pressionada.', 'As tarefas utilizavam semáforos de Dijkstra de  bits para garantir que nenhuma variável fosse sobrescrita.', 'O sistema operacional alternava os processos estaticamente a cada 0 segundos de relógio.', 'B'),
('Como era a estrutura da tabela de estados do carrossel no microprocessador?', 'Uma matriz tridimensional gravada em memória ROM não volátil.', 'Um banco de dados relacional gerido por SQL em disco rígido.', 'Uma pilha LIFO estruturada em linguagem Pascal com verificação de limites.', 'Um arquivo de texto plano lido a cada inicialização da máquina.', 'Registradores de memória mapeada onde os bits indicavam a posição física detectada por microswitches e os modos solicitados pelo software.', 'E'),
('Explique a mecânica exata do bug do contador de testes de calibração que resetava a cada 5 execuções no loop de checagem (Yakima).', 'O contador de verificação do colimador era armazenado em  byte; na 5ª iteração o valor passava de 55 para fazendo a rotina concluir que os testes haviam passado com sucesso sem ter checado o hardware.', 'O temporizador de  bits transbordava a cada 5 segundos e desligava a energia do hospital.', 'O loop contava até 5 e acionava a sirene de emergência da cidade.', 'A variável contava 5 pacientes atendidos e apagava o banco de dados do dia.', 'O sistema contava 5 cliques no teclado e travava a interface de vídeo.', 'A'),
('Como a ausência de uma arquitetura de proteção de memória no processador PDP- afetava o Therac-5?', 'Impedia a conexão de impressoras paralelas no console de comando.', 'Limitava o armazenamento do computador a apenas 0 fotos de raio-X por paciente.', 'Forçava o sistema a formatar o disco rígido a cada erro de sintaxe.', 'Permitia que qualquer tarefa com ponteiro corrompido sobrescrevesse posições de memória de outras tarefas ou do próprio núcleo do sistema operacional.', 'Causava superaquecimento nos circuitos lógicos centrais.', 'D'),
('Detalhe o papel do espelho de alinhamento óptico no carrossel de posições.', 'Projetar uma luz visível na pele do paciente para alinhar o campo de tratamento antes de disparar o feixe de radiação invisível.', 'Refletir o feixe de radiação de volta para o gerador para aumentar a potência.', 'Queimar as células doentes através de luz ultravioleta concentrada.', 'Permitir que o paciente veja seu próprio exame durante a aplicação.', 'Medir a reflexão dos elétrons na superfície da pele.', 'A'),
('Por que o uso de sinalizadores (flags) de um único byte sem operações atômicas (*read-modify-write*) gerava inconsistências?', 'Porque bytes individuais queimavam os circuitos do PDP- por excesso de corrente.', 'Porque o processador só aceitava variáveis do tipo ponto flutuante com  bits.', 'Porque sinalizadores de  byte eram automaticamente convertidos em zeros pelo compilador.', 'Porque geravam conflitos de endereçamento IP na placa de rede.', 'Porque uma interrupção podia ocorrer no meio da alteração do byte, deixando a variável em um estado parcialmente modificado e incorreto.', 'E'),
('Quais foram as falhas na gestão de configuração de software que permitiram os problemas no Therac-5?', 'Contratação de mais de 500 programadores que não conseguiam se comunicar por falha de idioma.', 'Uso exclusivo de ferramentas de desenvolvimento mantidas por estudantes de graduação sem supervisão.', 'Dependência de um único programador, ausência de revisão por pares (*code review*), falta de controle de versão e documentação técnica quase inexistente.', 'Adoção rígida da metodologia Agile com reuniões diárias e testes automatizados contínuos.', 'Terceirização total do código para uma empresa sem histórico em sistemas médicos.', 'C'),
('Explique como o software tratava o estado de "Pause" e como isso podia acumular parâmetros incorretos antes da liberação.', 'O modo Pause aumentava a potência do feixe em 0% a cada segundo pausado.', 'O estado de Pause mantinha as variáveis de configuração anteriores e permitia retomar o feixe sem revalidar completamente se o carrossel havia mudado de posição durante a pausa.', 'A pausa forçava o computador a ler as configurações salvas em uma fita magnética danificada.', 'A pausa apagava o registro de dose prescrita e definia a dose para o valor máximo por padrão.', 'A pausa reiniciava o processador apagando o histórico de comandos.', 'B'),
('De que maneira a dosimetria por software era afetada pela saturação das câmaras de ionização?', 'A câmara derretia o plastico da carcaça e obstruía a saída do feixe de radiação.', 'O sinal saturado invertia a polaridade dos motores do carrossel.', 'A dosimetria por software registrava valores negativos e devolvia a radiação para o gerador.', 'Diante de um pulso massivo de radiação, a câmara atingia a corrente limite de leitura, fornecendo um sinal saturado que o software interpretava como uma dose baixa ou nula de radiação.', 'A câmara gerava um curto-circuito que desligava a rede elétrica do hospital.', 'D'),
('Avalie a responsabilidade ética dos engenheiros envolvidos no caso sob os códigos modernos (IEEE/ACM).', 'Os engenheiros violaram o dever primário de priorizar a segurança pública e a vida humana ao ignorar relatórios de falhas graves e omitir testes adequados.', 'Os engenheiros agiram com perfeita conduta ética, pois o software sempre executa exatamente o que o código manda.', 'A responsabilidade ética cabe exclusivamente aos médicos que compraram o equipamento sem solicitar uma garantia estendida.', 'O código de ética da IEEE desobriga engenheiros de testar sistemas operacionais de tempo real.', 'A responsabilidade civil recai apenas sobre a administração da diretoria e nunca sobre os projetistas técnicos.', 'A'),
('Qual foi a mecânica do acidente em Tyler, Texas (março de 98), e como diferiu do acidente em Yakima?', 'Em Tyler ocorreu um incêndio elétrico na sala; em Yakima o erro foi causado por uma queda de raio na rede da cidade.', 'Em Tyler a máquina disparou no modo Ultrassom; em Yakima o disparo foi no modo Radiação Gama.', 'Não houve diferenças; ambos os acidentes foram causados pela quebra da correia do motor do carrossel.', 'Em Tyler o problema foi erro de digitação do médico; em Yakima foi falha mecânica pura.', 'Em Tyler, o acidente envolveu a edição rápida de parâmetros no VT00 (race condition em `Datain`); em Yakima, envolveu o estouro do contador de  byte (`Class`) no loop de calibração do carrossel.', 'E'),
('Como a premissa errônea de que "software não desgasta nem falha" afetou a análise FMEA da AECL?', 'Fez com que a AECL trocasse os chips do computador a cada 0 dias preventivamente.', 'Forçou os engenheiros a usarem apenas programas gravados em discos de pedra.', 'Levou a equipe a atribuir probabilidade zero de falha para o módulo de software, ignorando bugs lógicos na análise de riscos do sistema global.', 'Fez a fábrica focar todos os testes no consumo de tinta do monitor de vídeo.', 'Causou o abandono completo de qualquer teste de hardware mecânico.', 'C'),
('Descreva o funcionamento das câmaras de ionização duplas e por que não interromperam o feixe a tempo durante o disparo massivo.', 'As câmaras ficavam desligadas para economizar energia do sistema durante sessões com elétrons.', 'As câmaras serviam de redundância para medir a dose; no entanto, o tempo de resposta do laço de malha fechada do software era mais lento do que o pulso de overdose entregue em milissegundos.', 'As duas câmaras foram conectadas ao contrário pelos técnicos do hospital.', 'As câmaras de ionização funcionavam com mercúrio líquido, que congelava durante o funcionamento.', 'As câmaras mediam apenas a radiação de fundo da sala e não a do feixe principal.', 'B'),
('Como o sistema tratava as interrupções de hardware geradas pelo teclado na velocidade do buffer UART?', 'O sistema desligava a CPU a cada tecla pressionada para processar a entrada de dados.', 'O buffer UART acumulava  MB de dados antes de enviar as informações para o processador.', 'As teclas digitadas eram convertidas para linguagem Morse antes de serem processadas.', 'O teclado era desconectado eletricamente sempre que uma sessão de radioterapia iniciava.', 'O manipulador de interrupção do teclado sobrescrevia posições de memória sem bloquear adequadamente as seções críticas do laço principal.', 'E'),
('Analise o papel da cultura organizacional da AECL na negação inicial das falhas.', 'A empresa contratou auditores independentes assim que recebeu a primeira carta de reclamação do hospital.', 'Uma cultura defensiva e isolada levou a empresa a rejeitar alertas externos, priorizando a reputação institucional em detrimento da investigação transparente das reclamações médicas.', 'A cultura da empresa incentivava os funcionários a denunciar qualquer bug de software na imprensa.', 'A AECL encerrou imediatamente suas operações para focar na melhoria de seus processos de qualidade.', 'A diretoria incentivava o diálogo aberto e público com os pacientes afetados desde o primeiro dia.', 'B'),
('Por que a inclusão de um microswitch de hardware no carrossel teria evitado os acidentes mesmo com bugs de software?', 'Porque o microswitch enviaria um alerta por e-mail para a sede da AECL no Canadá.', 'Porque o microswitch corrigiria automaticamente os arquivos de código-fonte corrompidos no disco rígido.', 'Porque o chaveamento mecânico cortaria a alimentação elétrica do feixe de alta energia caso o carrossel estivesse na posição de Elétrons sem o alvo metálico, independentemente do software.', 'Porque a chave forçaria o operador a digitar uma senha de  caracteres a cada tratamento.', 'Porque impediria totalmente que o computador ligasse sem a calibração de fábrica.', 'C'),
('Explique como a rotina `Set_Bending_Magnet` interagia com os conversores digital-analógico (DAC).', 'A rotina convertia imagens digitais em som analógico para os alto-falantes do bunker.', 'A rotina ajustava o brilho e o contraste do monitor CRT do console.', 'A rotina lia os sinais da antena de televisão instalada no teto da clínica.', 'A rotina enviava valores numéricos aos DACs para ajustar a corrente dos eletroímãs que curvavam o feixe; ao usar parâmetros incorretos, o feixe saía desalinharado e descontrolado.', 'A rotina gerava ondas de rádio para resfriar os ímãs de curvatura.', 'D'),
('Como a validação baseada em testes de "caixa-preta" falhou em revelar os caminhos de execução contendo race conditions?', 'Os testes de caixa-preta avaliavam apenas pares de entrada/saída esperados sob condições normais, sem analisar o código fonte nem simular combinações assíncronas de temporização extremas.', 'Porque os testes de caixa-preta só podem ser aplicados em equipamentos mecânicos, e nunca em computadores.', 'Porque os testadores de caixa-preta não tinham acesso ao gabinete físico da máquina.', 'Os testes de caixa-preta revelaram todos os acidentes, mas a gerência decidiu ignorá-los.', 'Porque exigiam o uso de linguagem de montagem avançada não suportada pelo PDP-.', 'A'),
('Qual foi o impacto da falta de logs persistentes em disco/fita na reconstrução post-mortem dos acidentes?', 'Permitiu que o computador rodasse duas vezes mais rápido durante o atendimento aos pacientes.', 'Evitou que a empresa fosse multada por acumular lixo digital em seus servidores.', 'Fez com que os operadores fossem forçados a anotar os dados de cada segundo em blocos de papel.', 'Reduziu o custo de fabricação do sistema de armazenamento em 50%.', 'Dificultou a identificação da causa raiz, pois o estado de memória se perdia quando a máquina era reiniciada após as falhas.', 'E'),
('Como as diretrizes do FDA "Corrective Action Plan" (CAP) reformularam a aprovação de dispositivos médicos de Classe III?', 'Proibiram a utilização de qualquer tipo de tela colorida nos consoles de controle de equipamentos médicos.', 'Passaram a exigir documentação de ciclo de vida de software, análise formal de riscos, validação de software e testes de integração de segurança antes da comercialização.', 'Exigiram que todos os dispositivos médicos fossem construídos exclusivamente com peças de madeira e latão.', 'Eliminaram a necessidade de ensaios clínicos para novos equipamentos radiológicos.', 'Permitiram a comercialização de softwares médicos sem testes de validação prévia.', 'B'),
('Qual era a função da rotina de verificação de consistência de fundo (*background check*) e por que ela não suspendeu o feixe?', 'Mudar o papel de parede da tela do operador a cada 0 minutos.', 'Limpar os arquivos temporários do sistema operacional durante a madrugada.', 'Checava periodicamente parâmetros de segurança em segundo plano, mas era suprimida ou ultrapassada pelas rotinas de interrupção de alta prioridade acionadas pela digitação.', 'Verificar a autenticidade da licença comercial do software junto ao governo canadense.', 'Realizar cópias de segurança do prontuário médico a cada hora cheia.', 'C'),
('Explique o fenômeno físico da Queimadura Radiológica Profunda provocada pelo feixe direto de 5 MeV sem atenuação.', 'A radiação aqueceu a superfície da pele a mais de 000 °C em um milissegundo, transformando a pele em cinzas instantaneamente.', 'Os elétrons causaram um choque elétrico que queimou os nervos periféricos sem afetar os órgãos internos.', 'O feixe congelou a água intracelular, provocando gangrena por congelamento instantâneo.', 'O feixe de alta energia depositou uma enorme densidade de ionização nos tecidos profundos, destruindo estruturas celulares e causando necrose sem necessariamente queimar a epiderme de imediato.', 'A radiação ionizante alterou a pigmentação superficial da pele sem causar danos celulares internos.', 'D'),
('Como a modelagem por métodos formais (como Redes de Petri) teria identificado os estados inválidos do Therac-5?', 'Ao mapear todos os estados possíveis e transições do sistema, a análise revelaria estados nos quais o feixe poderia ser ativado com o carrossel em posição incorreta.', 'Ao reescrever o código do sistema operacional automaticamente para a linguagem C.', 'Ao impedir que o operador utilizasse a tecla \''Backspace\'' no terminal VT00.', 'Calculando a velocidade do vento na sala do acelerador.', 'Substituindo todas as variáveis lógicas por circuitos analógicos.', 'A'),
('Qual foi o papel da imprensa e das publicações científicas na divulgação do problema antes dos recalls oficiais?', 'Alertaram a comunidade médica e outros hospitais sobre os riscos do equipamento, forçando o compartilhamento de informações que a fabricante omitia.', 'Tiveram um papel irrelevante, pois a população não tinha interesse em notícias sobre tecnologia médica.', 'Criaram notícias falsas para favorecer fabricantes concorrentes alemãs.', 'Defenderam a AECL ao afirmar que os pacientes sofriam de alucinações coletivas.', 'Publicaram o código-fonte completo da máquina em jornais de grande circulação.', 'A'),
('Compare o modelo de acoplamento do sistema do Therac-5 com a teoria de "Acidentes Normais" de Charles Perrow.', 'O sistema era fracamente acoplado, o que garantia que erros no computador nunca afetassem o paciente.', 'A teoria de Perrow afirma que acidentes em aceleradores de partículas são geometricamente impossíveis.', 'O Therac-5 demonstrou que sistemas complexos são imunes a condições de corrida devido à auto-organização do código.', 'O Therac-5 era um sistema fortemente acoplado e interativo; pequenas falhas em componentes de software encadearam impactos catastróficos imprevisíveis no hardware.', 'O modelo de Perrow classifica o Therac-5 como um sistema linear sem interações complexas ocultas.', 'D'),
('Desenvolva conceitualmente o topo de uma Árvore de Análise de Falhas (FTA) para o evento: "Emissão de feixe de alta corrente sem espalhador".', 'O topo é uma porta \''OU\'' (OR) combinando apenas a temperatura da sala e o peso do paciente.', 'O topo exige uma porta lógica \''E\'' ''AND''unindo: "Modo Raio-X de alta corrente selecionado" E "Alvo/espalhador ausente da posição física".', 'A árvore de falhas deve conter apenas nós de hardware, sem incluir eventos de software.', 'O evento de topo deve ser definido como "Erro exclusivo de operação do usuário".', 'O topo requer uma porta \''NÃO\''NOT conectada ao relógio principal da CPU.', 'B'),
('Por que o uso de buffers de entrada sem tratamento de overflow contribuiu para a corrupção do estado da interface?', 'O estouro de buffer limpava toda a memória ROM da máquina, travando a CPU permanentemente.', 'Os buffers sem tratamento aumentavam o consumo de energia da tela de vídeo CRT.', 'O estouro do buffer enviava os dados do paciente para a impressora de relatórios.', 'O estouro do buffer redefinia a senha de administrador do sistema operacional.', 'A digitação rápida de comandos excedia a capacidade do buffer, fazendo caracteres extras sobrescreverem ponteiros de memória de variáveis vizinhas.', 'E'),
('Como a alteração de requisitos durante o ciclo de vida do projeto comprometeu a coerência do código original do Therac-5?', 'A mudança de requisitos forçou a troca do sistema operacional por um compilador de jogos de arcade.', 'Os requisitos originais previam o uso da máquina apenas para fins estéticos, mas foram alterados para fins terapêuticos.', 'Requisitos de automação foram sobrepostos a uma arquitetura de software antiga sem que ela fosse redesenhada para suportar operação 00% autônoma.', 'As alterações de requisitos foram feitas sem o consentimento da equipe de engenheiros do projeto.', 'A eliminação dos requisitos de segurança reduziu o tempo de compilação do código.', 'C'),
('De que modo a análise estática de código moderno preveniria o estouro de variáveis e atalhos na interface no Therac-5?', 'Identificaria em tempo de compilação o risco de estouro da variável de 8 bits (`Class`) e o uso de recursos compartilhados sem proteção atômica.', 'Reescreveria o código Assembly para linguagem de máquina em tempo de execução sem passar pela CPU.', 'Substituiria todas as variáveis numéricas por valores de texto fixos.', 'A análise estática de código impediria a digitação de caracteres minúsculos no terminal.', 'Desativaria automaticamente o teclado durante sessões longas de radioterapia.', 'A'),
('Como o Efeito Cherenkov foi observado visualmente por pacientes atingidos pelo feixe durante o disparo?', 'A sala de tratamento acendia lâmpadas estroboscópicas vermelhas de emergência.', 'O monitor de vídeo projetava arco-íris na parede do bunker.', 'Os pacientes observavam faíscas elétricas saltando das tomadas da parede da sala.', 'Os pacientes viam um clarão brilhante de luz azul/branca dentro de seus olhos, causado pela radiação atravessando os fluidos do globo ocular a uma velocidade superior à da luz no meio.', 'O feixe refletia nas paredes de chumbo gerando uma luz verde fluorescente.', 'D'),
('Qual é a importância da redundância diversificada (hardware vs. software) na engenharia de sistemas críticos de segurança?', 'Permitiu que a máquina continue operando em dobro da potência caso um dos sistemas falhe.', 'Garante que, se o software falhar devido a um erro lógico imprevisível, o circuito físico de hardware atue de forma independente para manter o sistema em estado seguro.', 'Serve para duplicar o preço final do equipamento e aumentar o lucro do fabricante.', 'Reduz o número de cabos elétricos necessários para conectar o console de controle.', 'Elimina completamente a necessidade de testes de integração lógica.', 'B'),
('Proponha a arquitetura de uma intertrava física independente para ser acoplada em um acelerador linear moderno.', 'Um programa de computador escrito em Python instalado no computador pessoal do médico.', 'Um fusível comum instalado na tomada de parede do consultório.', 'Uma chave manual mantida no bolso do operador durante o expediente.', 'Um circuito lógico integrado acoplado diretamente ao painel frontal sem sensores externos.', 'Um circuito eletromecânico e óptico isolado da CPU principal, alimentado por fonte própria, que lê sensores físicos de posição do carrossel e corta a energia do feixe caso detecte desalinhamento.', 'E'),
('Que lição fundamental sobre a relação entre automação e responsabilidade humana o Therac-5 ensina?', 'A automação deve ser evitada em qualquer tipo de indústria ou serviço de saúde.', 'Os operadores humanos devem ser totalmente responsabilizados por todas as falhas ocorridas em máquinas automatizadas.', 'A automação deve servir para apoiar os operadores, mantendo transparência, redundância e mecanismos físicos de segurança, sem substituir o julgamento humano nem criar uma falsa premissa de infalibilidade do software.', 'O software deve sempre ter controle absoluto e autoridade superior sobre qualquer comando de desligamento humano.', 'A responsabilidade técnica deve ser transferida inteiramente para os órgãos reguladores governamentais.', 'C');
